class BasicSegmenter {
  constructor(granularity) { this.granularity = granularity; }
  segment(text) {
    const parts = [];
    for (const segment of text.split('')) parts.push({ segment });
    return parts;
  }
  resolvedOptions() { return { locale: 'und', granularity: this.granularity }; }
}
export function resolveSegmenterConstructor(intl) { return intl?.Segmenter ?? null; }
const defaultSegmenterConstructor = resolveSegmenterConstructor(globalThis.Intl);
export function createSegmenter(granularity, segmenterConstructor = defaultSegmenterConstructor) {
  return segmenterConstructor ? new segmenterConstructor(undefined, { granularity }) : new BasicSegmenter(granularity);
}
const graphemeSegmenter = createSegmenter('grapheme');
export function getGraphemeSegmenter() { return graphemeSegmenter; }
export function render(text) {
  let out = '';
  for (const part of getGraphemeSegmenter().segment(text)) out += `[${part.segment}]`;
  return `${out}:${createSegmenter('word', null).resolvedOptions().locale}`;
}
